#include <bits/stdc++.h>
using namespace std;

int main() {
	string s, t;
	cin >> s >> t;
	vector<string> ans;
	int n = s.size();
	while (s != t) {
		string nxt(n, 'z');
		for (int i = 0; i < n; i++) {
			if (s[i] != t[i]) {
				string tmp = s;
				tmp[i] = t[i];
				nxt = min(nxt, tmp);
			}
		}
		ans.push_back(nxt);
		s = nxt;
	}
	int sz = ans.size();
	cout << sz << '\n';
	for (string e : ans) cout << e << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
	string s, t;
	cin >> s >> t;
	vector<string> ans;
	vector<int> v;
	int n = s.size();
	for (int i = 0; i < n; i++) {
		if (s[i] > t[i]) v.push_back(i);
	}
	for (int i = n - 1; i >= 0; i--) {
		if (s[i] < t[i]) v.push_back(i);
	}
	int sz = v.size();
	for (int i = 0; i < sz; i++) {
		s[v[i]] = t[v[i]];
		ans.push_back(s);
	}
	cout << sz << '\n';
	for (string e : ans) cout << e << '\n';
}
